	Say("王佐：帮主、杨右使和泰山派兄弟们已经前往营救其它将军。盟主，我们要加紧行动。", 63);
	Say("卢青：听说秦老贼正加派禁军赶来，掌门师兄，怎么办？", 83);
	Say("牛皋：我们跟秦老贼拼了！");
	
	Say("张琳心：牛将军，我们不能鲁莽行事！",21);
	Watch("独孤剑", "张琳心", 0);
	Say("独孤剑：琳心，你有什么好主意。", 1);
	
	AddNpc("npc002_张如梦.ini", 7, 69, 6);	
	AddNpc("npc005_南宫彩虹.ini", 7, 71, 6);	
	Say("张如梦：看来我们来得正好！",11);
	
	SetPlayerDir(2);
	SetNpcDir("张琳心",2);
	SetNpcDir("卢青",3);
	SetNpcDir("牛皋",2);
	SetNpcDir("王佐",2);
	SetNpcDir("罗天强",3);	
	NpcGotoEx("张如梦",12,69);
	NpcGoto("南宫彩虹",12,70);
	SetNpcDir("张如梦",6);
	SetNpcDir("南宫彩虹",6);
	
	Say("张琳心：哥哥！", 21);
	Say("独孤剑：张兄，南宫姑娘……", 1);
	Say("张琳心：还不叫嫂嫂！",23);
	Say("南宫彩虹：……",30);
	Say("张如梦：临安的事情我们都听说了，彩虹和我特地赶来帮助大家一起营救岳元帅！",12);
	Say("张琳心：那太好了！",21);
	SetPlayerDir(7);
	SetNpcDir("张琳心",7);
	Say("王佐：如此甚好！盟主，不如我们兵分三路……",63);
	Say("独孤剑：好！我和琳儿去营救岳元帅。",1);
	Say("独孤剑：师弟，你和王将军他们前去阻截增援的禁军……",1);
	SetNpcDir("张如梦",1);
	SetPlayerDir(2);
	SetNpcDir("张琳心",2);
	Say("南宫彩虹：那我和如梦就去秦府，杀了那个老贼！",29);
	Say("张如梦：好！诛此国贼，为天下除害！",11);
	
	SetNpcDir("张如梦",1);
	Say("独孤剑：张兄，秦贼奸诈阴险，你们要小心！",1);
	Say("张琳心：哥哥……你们要保重！",21);
	Say("张如梦：你们也要小心。我们先走一步！",11);
	
	NpcGotoEx("张如梦",7,69);
	NpcGoto("南宫彩虹",7,71);
	DelNpc("张如梦");
	DelNpc("南宫彩虹");
	
	SetPlayerDir(7);
	SetNpcDir("张琳心",7);
	SetNpcDir("卢青",4);
	SetNpcDir("罗天强",4);
	SetNpcDir("牛皋",3);	
	SetNpcDir("王佐",3);
	Say("王佐：那我们也马上行动。盟主，小心！",63);
	Say("卢青：师兄，保重！",83);
	Say("独孤剑：嗯！",1);
	
	
	NpcGotoEx("牛皋", 18, 71);
	NpcGotoEx("王佐", 18, 72);
	NpcGotoEx("罗天强", 18, 74);
	NpcGoto("卢青", 18, 73);
	
	Sleep(300);
	DelNpc("牛皋");
	DelNpc("卢青");
	DelNpc("王佐");
	DelNpc("罗天强");
		
	Watch("独孤剑", "张琳心", 0);
	Say("张琳心：独孤哥哥，我们走吧！", 21);
	Say("独孤剑：琳儿，要小心！", 1);
	Assign($Result, 5);
	SetNpcKind("张琳心", 3);
	SetPartnerLevel("张琳心", 46);
	SetNpcRelation("张琳心", 0);
